from collections import deque


class TreeNode:
    def __init__(self, val: int) -> None:
        self.val = val
        self.left: TreeNode | None = None
        self.right: TreeNode | None = None


# Level order: the children of each node come next, null for a missing one.
def build_tree(tokens: list[str]) -> TreeNode | None:
    nodes = [None if token == "null" else TreeNode(int(token)) for token in tokens]
    child = 1
    for node in nodes:
        if node is not None:
            node.left = nodes[child] if child < len(nodes) else None
            node.right = nodes[child + 1] if child + 1 < len(nodes) else None
            child += 2
    return nodes[0] if nodes else None


def level_order(root: TreeNode | None) -> list[list[int]]:
    levels: list[list[int]] = []
    queue = deque([root]) if root is not None else deque()
    while queue:
        level = []
        for _ in range(len(queue)):
            node = queue.popleft()
            level.append(node.val)
            if node.left is not None:
                queue.append(node.left)
            if node.right is not None:
                queue.append(node.right)
        levels.append(level)
    return levels


root = build_tree(input().split())
for level in level_order(root):
    print(" ".join(str(value) for value in level))

